function toggleDarkMode(){ state.settings.darkMode=!!el('dark-mode-toggle').checked; saveSettings(); applySettings(); }
function toggleBackgroundSoundEnabled(){ const src=document.activeElement && (document.activeElement.id==='exam-bg-sound-enabled-toggle' || document.activeElement.id==='bg-sound-enabled-toggle') ? document.activeElement : el('bg-sound-enabled-toggle'); state.settings.bgSoundEnabled=!!src.checked; saveSettings(); applySettings(); }
